                    else
                    {
                        sw.SendUndef();
                    }

                    if (pointOnSurfacePairWithRange.HasUpperLimitYaw)
                    {
                        sw.Send(pointOnSurfacePairWithRange.UpperLimitYaw());
                    }
                    else
                    {
                        sw.SendUndef();
                    }

                    if (pointOnSurfacePairWithRange.HasLowerLimitPitch)
                    {
                        sw.Send(pointOnSurfacePairWithRange.LowerLimitPitch());
                    }
                    else
                    {
                        sw.SendUndef();
                    }

                    if (pointOnSurfacePairWithRange.HasUpperLimitPitch)
                    {
                        sw.Send(pointOnSurfacePairWithRange.UpperLimitPitch());
                    }
                    else
                    {
                        sw.SendUndef();
                    }

                    if (pointOnSurfacePairWithRange.HasLowerLimitRoll)
                    {
                        sw.Send(pointOnSurfacePairWithRange.LowerLimitRoll());
                    }
                    else
                    {
                        sw.SendUndef();
                    }

                    if (pointOnSurfacePairWithRange.HasUpperLimitRoll)
                    {
                        sw.Send(pointOnSurfacePairWithRange.UpperLimitRoll());
                    }
                    else
                    {
                        sw.SendUndef();
                    }
                }
            }
            else if (ent.GetOrderKinematicPair().IsKind(typeof(PlanarCurvePair)))
            {
                sw.StartEntity("PLANAR_CURVE_PAIR");
                PlanarCurvePair planarCurvePair = ent.GetOrderKinematicPair() as PlanarCurvePair;
                // Own fields of PlanarCurvePair

                sw.Send(planarCurvePair.Curve1());

                sw.Send(planarCurvePair.Curve2());

                sw.StartEntity("(PLANAR_CURVE_PAIR_RANGE");
                if (ent.GetOrderKinematicPair().IsKind(typeof(PlanarCurvePairRange)))
                {
                    PlanarCurvePairRange planarCurvePairRange = ent.GetOrderKinematicPair() as PlanarCurvePairRange;
                    // Own fields of PlanarCurvePairRange

                    sw.Send(planarCurvePairRange.RangeOnCurve1());

                    sw.Send(planarCurvePairRange.RangeOnCurve2());
                }
            }
            else if (ent.GetOrderKinematicPair().IsKind(typeof(SurfacePair)))
            {
                sw.StartEntity("SURFACE_PAIR");
                SurfacePair surfacePair = ent.GetOrderKinematicPair() as SurfacePair;
                // Own fields of SurfacePair

                sw.Send(surfacePair.Surface1());

                sw.Send(surfacePair.Surface2());

                sw.SendBoolean(surfacePair.Orientation());

                sw.StartEntity("(SURFACE_PAIR_WITH_RANGE");
                if (ent.GetOrderKinematicPair().IsKind(typeof(SurfacePairWithRange)))
                {
                    SurfacePairWithRange surfacePairWithRange = ent.GetOrderKinematicPair() as SurfacePairWithRange;
                    // Own fields of SurfacePairWithRange

                    sw.Send(surfacePairWithRange.RangeOnSurface1());

                    sw.Send(surfacePairWithRange.RangeOnSurface2());

                    if (surfacePairWithRange.HasLowerLimitActualRotation)
                    {
                        sw.Send(surfacePairWithRange.LowerLimitActualRotation());
                    }
                    else
                    {
                        sw.SendUndef();
                    }

                    if (surfacePairWithRange.HasUpperLimitActualRotation)
                    {
                        sw.Send(surfacePairWithRange.UpperLimitActualRotation());
                    }
                    else
                    {
                        sw.SendUndef();
                    }
                }
            }
        }

        // Own fields of RepresentationItem
        sw.StartEntity("REPRESENTATION_ITEM");
        sw.Send(ent.Name());
    }

    public void Share(ActuatedKinPairAndOrderKinPair ent, EntityIterator iter)
    {
        iter.AddItem(ent.GetOrderKinematicPair());
        iter.AddItem(ent.GetOrderKinematicPair().Joint());
        iter.AddItem(ent.GetActuatedKinematicPair());
        iter.AddItem(ent.GetOrderKinematicPair().ItemDefinedTransformation());
    }
}
